/**
 * @summary Netopia payment IPN callback
 */
export const netopiaCallback = async (netopiaCallbackBody: NetopiaCallbackBody, options?: RequestInit): Promise<string> => {
    const formUrlEncoded = new URLSearchParams();
if(netopiaCallbackBody.env_key !== undefined) {
 formUrlEncoded.append(`env_key`, netopiaCallbackBody.env_key);
 }
if(netopiaCallbackBody.data !== undefined) {
 formUrlEncoded.append(`data`, netopiaCallbackBody.data);
 }

  return customFetch<string>(getNetopiaCallbackUrl(),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded', ...options?.headers },
    body:
      formUrlEncoded,
  }
);}




